"use client"

import { useState, useEffect, useRef } from "react"
import { Button } from "@/components/ui/button"
import { Input } from "@/components/ui/input"
import { Label } from "@/components/ui/label"
import { User, Lock, LogIn, Loader2 } from "lucide-react"
import { useDictionary } from "@/components/dictionary-provider"
import { useAuth } from "@/components/auth-provider"
import { createClient } from "@/lib/supabase"
import { useRouter } from "next/navigation"
import Link from "next/link"
import Image from "next/image"
import { FullPageLoader } from "@/components/full-page-loader"
import { ButtonLoader } from "@/components/button-loader"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"

import { toast } from "sonner"

export default function LoginPage() {
  const { dict, config, lang, setLanguage } = useDictionary()
  const { user, profile, loading } = useAuth()
  const router = useRouter()
  const supabase = createClient()
  const passwordRef = useRef<HTMLInputElement>(null)

  const [username, setUsername] = useState("")
  const [password, setPassword] = useState("")
  const [loginError, setLoginError] = useState("")
  const [isSubmitting, setIsSubmitting] = useState(false)

  // Forgot Password State
  const [isForgotOpen, setIsForgotOpen] = useState(false)
  const [forgotEmail, setForgotEmail] = useState("")
  const [forgotLoading, setForgotLoading] = useState(false)

  const handleForgotSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    setForgotLoading(true)

    try {
      const response = await fetch('/api/auth/forgot-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: forgotEmail })
      })

      const result = await response.json()

      if (result.error) {
        toast.error(result.error)
      } else {
        toast.success(dict.MSG_RESET_SENT || "Security link dispatched", {
          description: "If an account exists with this email, you will receive a link shortly.",
          duration: 8000,
        })
        setForgotEmail("")
        setIsForgotOpen(false) // Close dialog on success
      }
    } catch (err: any) {
      toast.error("An unexpected error occurred.")
    } finally {
      setForgotLoading(false)
    }
  }

  // Focus password on error
  useEffect(() => {
    if (loginError && passwordRef.current) {
      passwordRef.current.focus()
      passwordRef.current.select() // Select text to make it easier to re-type
    }
  }, [loginError])

  // Redirect if ALREADY logged in on mount
  useEffect(() => {
    if (!loading && user && profile?.is_active) {
      router.push("/dashboard")
    }
  }, [loading, user, profile, router])

  const toggleLanguage = () => {
    setLanguage(lang === 'en' ? 'id' : 'en')
  }

  const handleSubmit = async (e: React.SyntheticEvent<HTMLFormElement, SubmitEvent>) => {
    e.preventDefault()
    setIsSubmitting(true)
    setLoginError("")
    console.log("Login: Starting submission for", username)

    const timeoutId = setTimeout(() => {
      console.error("Login: Submission timed out after 15s")
      setLoginError(dict.ERROR_TIMEOUT || "Request timed out. Please check your connection and try again.")
      setIsSubmitting(false)
    }, 15000)

    try {
      let emailToUse = username

      // 1. Username lookup with short 5s timeout & fallback
      if (!username.includes("@")) {
        console.log("Login: Looking up email for username")

        // We create a promise that resolves after 5 seconds to skip the lookup
        const lookupTimeout = new Promise((resolve) => setTimeout(() => resolve("TIMEOUT"), 5000))

        try {
          const result = await Promise.race([
            supabase.rpc('get_email_from_username', { target_username: username.toLowerCase() }),
            lookupTimeout
          ])

          if (result === "TIMEOUT") {
            console.warn("Login: Username lookup timed out, falling back to direct login")
          } else {
            const { data: emailResult, error: lookupError } = result as any
            if (!lookupError && emailResult) {
              emailToUse = emailResult
              console.log("Login: Email found:", emailToUse)
            } else {
              console.warn("Login: Username lookup failed, using input as is", lookupError)
            }
          }
        } catch (e) {
          console.error("Login: Lookup error", e)
        }
      }

      // 2. Sign In      console.log("Login: Attempting auth.signInWithPassword")
      const { data: { user: authedUser }, error: authError } = await supabase.auth.signInWithPassword({
        email: emailToUse,
        password: password,
      })

      if (authError) {
        console.error("Login: Auth error", authError)
        setLoginError(dict.LOGIN_ERROR_INVALID || "Invalid username or password.")
        clearTimeout(timeoutId)
        return
      }

      if (authedUser) {
        console.log("Login: Auth successful, user ID:", authedUser.id)
        // 3. Manual Profile Check for Redirect
        console.log("Login: Checking profile status")
        const { data: profileData, error: profileError } = await supabase
          .from('profiles')
          .select('is_active')
          .eq('auth_id', authedUser.id) // Corrected to auth_id
          .single()

        if (profileError) {
          console.error("Login: Profile fetch error", profileError)
          setLoginError(dict.ERROR_VERIFY_STATUS || "Unable to verify account status.")
          clearTimeout(timeoutId)
          return
        }

        if (profileData && !profileData.is_active) {
          console.warn("Login: Account pending approval")
          setLoginError(dict.LOGIN_ERROR_PENDING || "Your account is pending approval.")
          await supabase.auth.signOut()
        } else if (profileData?.is_active) {
          console.log("Login: Account active, updating last_login")
          // 4. Update last_login
          await supabase
            .from('profiles')
            .update({ last_login: new Date().toISOString() })
            .eq('auth_id', authedUser.id) // Corrected to auth_id

          console.log("Login: Redirecting to dashboard")
          router.push("/dashboard")
        } else {
          console.error("Login: Profile record missing for user", authedUser.id)
          setLoginError((dict as any).LOGIN_ERROR_NO_PROFILE || "Account authenticated but no profile found. Please contact support.")
        }
      }
    } catch (err) {
      console.error("Login: Unexpected error", err)
      setLoginError(dict.ERROR_UNEXPECTED || "An unexpected error occurred.")
    } finally {
      clearTimeout(timeoutId)
      setIsSubmitting(false)
    }
  }
  if (loading) {
    return <FullPageLoader />
  }

  return (
    <div className="login-background">
      <div className="login-card relative">
        <div className="lang-toggle-wrapper">
          <button
            onClick={toggleLanguage}
            className="lang-toggle-btn"
            title={dict.TOOLTIP_LANG || "Switch Language"}
          >
            {lang.toUpperCase()}
          </button>
        </div>

        <div className="banner-container h-92">
          <Image
            src={config.assets.loginImage}
            alt="Login Header"
            fill
            className="object-cover object-top transition-all duration-500"
            priority
          />
          <div className="banner-overlay" />
          <div className="banner-blur-mask" />

          <div className="absolute inset-x-0 bottom-0 z-20 p-8 pb-4 text-center">
            <div className="flex justify-center mb-2">
              <div className="bg-background/20 backdrop-blur-md p-3 rounded-xl border border-white/20">
                <LogIn className="size-8 text-foreground shadow-sm" />
              </div>
            </div>
            <h1 className="text-3xl font-bold tracking-tight text-foreground drop-shadow-md">{config.brandName}</h1>
            <p className="text-foreground mt-1 text-pretty text-sm">
              {dict.LOGIN_SUBTITLE}
            </p>
            <div className="min-h-[60px] flex items-start justify-center mt-2">
              {loginError && (
                <div className="w-full p-3 text-sm text-destructive bg-background/40 backdrop-blur-sm border border-destructive/50 rounded-md animate-in fade-in duration-700">
                  {loginError}
                </div>
              )}
            </div>
          </div>
        </div>

        <div className="p-8 pt-4">
          <form onSubmit={handleSubmit} className="flex flex-col gap-6">
            <div className="flex flex-col gap-2">
              <Label htmlFor="username">{dict.LABEL_USERNAME}</Label>
              <div className="relative group">
                <User className="absolute left-3 top-3 size-4 text-muted-foreground transition-colors group-focus-within:text-primary" />
                <Input
                  id="username"
                  placeholder="username / email"
                  className="pl-10"
                  value={username}
                  onChange={(e) => setUsername(e.target.value)}
                  required
                  disabled={isSubmitting}
                />
              </div>
            </div>

            <div className="flex flex-col gap-2">
              <Label htmlFor="password">{dict.LABEL_PASSWORD}</Label>
              <div className="relative group">
                <Lock className="absolute left-3 top-3 size-4 text-muted-foreground transition-colors group-focus-within:text-primary" />
                <Input
                  id="password"
                  ref={passwordRef}
                  type="password"
                  placeholder={dict.PLACEHOLDER_PASSWORD}
                  className="pl-10 text-2xl"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  required
                  disabled={isSubmitting}
                />
              </div>
            </div>

            <Button type="submit" className="w-full h-11 interactive-click mt-2" disabled={isSubmitting}>
              {isSubmitting ? (
                <ButtonLoader />
              ) : (
                <LogIn data-icon="inline-start" />
              )}
              {dict.BUTTON_LOGIN}
            </Button>
          </form>

          <div className="mt-8 flex flex-col items-center gap-4">
            <div className="text-center text-sm text-muted-foreground">
              {dict.TEXT_NO_ACCOUNT}{" "}
              <Link href="/signup" className="font-semibold text-primary underline-offset-4 hover:underline">
                {dict.LINK_SIGNUP}
              </Link>
            </div>

            <button
              type="button"
              onClick={() => setIsForgotOpen(true)}
              className="text-xs text-primary font-medium hover:underline underline-offset-4"
            >
              {dict.LINK_FORGOT_PWD || "Forgot password?"}
            </button>
          </div>

          <div className="mt-8 text-center text-xs text-muted-foreground">
            {dict.COPYRIGHT}
          </div>
        </div>
      </div>

      <Dialog open={isForgotOpen} onOpenChange={setIsForgotOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>{dict.TITLE_FORGOT_PWD || "Reset Password"}</DialogTitle>
            <DialogDescription>
              {dict.DESC_FORGOT_PWD || "Enter your email address and we'll send you a link to reset your password."}
            </DialogDescription>
          </DialogHeader>

          <form onSubmit={handleForgotSubmit} className="space-y-4 p-4">
            <div className="space-y-2">
              <Label htmlFor="forgot-email">{dict.LABEL_EMAIL}</Label>
              <Input
                id="forgot-email"
                type="email"
                placeholder="name@example.com"
                value={forgotEmail}
                onChange={(e) => setForgotEmail(e.target.value)}
                required
                className="text-sm"
                disabled={forgotLoading}
              />
            </div>

            <DialogFooter className="flex flex-col sm:flex-row gap-2 pt-2">
              <Button
                type="button"
                variant="outline"
                onClick={() => setIsForgotOpen(false)}
                className="w-full sm:flex-1"
                disabled={forgotLoading}
              >
                {dict.BUTTON_CANCEL}
              </Button>
              <Button
                type="submit"
                className="w-full sm:flex-1"
                disabled={forgotLoading}
              >
                {forgotLoading ? <ButtonLoader /> : null}
                {dict.BUTTON_SEND_LINK || "Send Link"}
              </Button>
            </DialogFooter>
          </form>
        </DialogContent>
      </Dialog>
    </div>
  )
}
